:250px;width:calc(100% - 250px);padding:28px}.top{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:24px}.top h1{margin:0;font-size:30px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.card{background:var(--card);border:1px solid var(--line);border-radius:20px;padding:20px;box-shadow:var(--shadow)}.metric{font-size:28px;font-weight:900;margin-top:8px}.grid{display:grid;grid-template-columns:1.4fr .8fr;gap:18px;margin-top:18px}.section{display:none}.section.active{display:block}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse;min-width:720px}.table th,.table td{padding:13px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}.badge{display:inline-flex;padding:6px 9px;border-radius:999px;font-size:12px;font-weight:800;background:#f2f4f7}.b-new{background:#fff4cc}.b-confirmed{background:#dbeafe}.b-preparing{background:#ede9fe}.b-delivering{background:#cffafe}.b-completed{background:#dcfce7}.b-cancelled{background:#fee2e2}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px}.toast{position:fixed;right:20px;bottom:20px;background:#111827;color:#fff;padding:13px 17px;border-radius:12px;display:none;z-index:9}.empty{text-align:center;padding:40px;color:var(--muted)}@media(max-width:1000px){.cards{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}@media(max-width:700px){.side{width:72px;padding:16px 8px}.side .brand{font-size:0;text-align:center}.side .brand:after{content:'🍔';font-size:24px}.nav button{font-size:0;text-align:center}.nav button:first-letter{font-size:20px}.main{margin-left:72px;width:calc(100% - 72px);padding:16px}.cards{grid-template-columns:1fr 1fr}.top h1{font-size:22px}.card{padding:15px}}
