<section id="home" class="section active"><div class="cards"><div class="card">📦 Jami buyurtmalar<div id="morders" class="metric">—</div></div><div class="card">🆕 Yangi<div id="mnew" class="metric">—</div></div><div class="card">📅 Bugun<div id="mtoday" class="metric">—</div></div><div class="card">💰 Tushum<div id="mrev" class="metric">—</div></div></div><div class="grid"><div class="card"><h3>Buyurtmalar oqimi</h3><canvas id="chart" height="150"></canvas></div><div class="card"><h3>Do‘kon ma’lumotlari</h3><div id="quick" class="muted">Yuklanmoqda...</div></div></div></section>
<section id="orders" class="section"><div class="card"><div class="toolbar"><button class="btn ghost" onclick="loadOrders()">↻ Yangilash</button><select id="filter" onchange="loadOrders()"><option value="">Barchasi</option><option>new</option><option>confirmed</option><option>preparing</option><option>delivering</option><option>completed</option><option>cancelled</option></select></div><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Mijoz</th><th>Aloqa</th><th>Manzil</th><th>Summa</th><th>Vaqt</th><th>Status</th></tr></thead><tbody id="ordersBody"></tbody></table></div></div></section>
<section id="products" class="section"><div class="card"><h2>Mahsulotlar</h2><p class="muted">Mavjud bazadagi jadvallar aniqlanadi. Mahsulotlar uchun alohida boshqaruvni ulash mumkin bo‘lgan jadval shu yerda ko‘rsatiladi.</p><div id="tables"></div></div></section>
<section id="customers" class="section"><div class="card"><h2>Mijozlar</h2><p class="muted">Buyurtmalardan kelgan mijozlar va aloqa ma’lumotlari.</p><div class="table-wrap"><table class="table"><thead><tr><th>Mijoz</th><th>Telefon</th><th>Manzil</th><th>Buyurtmalar</th></tr></thead><tbody id="customersBody"></tbody></table></div></div></section>
<section id="settings" class="section"><div class="card"><h2>Do‘kon sozlamalari</h2><form id="settingsForm"><div class="field"><label>Do‘kon nomi</label><input name="store_name"></div><div class="field"><label>Telefon</label><input name="phone"></div><div class="field"><label>Manzil</label><input name="address"></div><div class="field"><label>Dastavka haqida</label><textarea name="delivery_note"></textarea></div><button class="btn primary">Saqlash</button></form></div></section>
</main></div><div id="toast" class="toast"></div><script>
const api=(a,o={})=>fetch('admin_pro_api.php?action='+a,o).then(r=>r.json());
const toast=x=>{let t=document.querySelector('#toast');t.textContent=x;t.style.display='block';setTimeout(()=>t.style.display='none',2200)};
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.section').forEach(x=>x.classList.remove('active'));document.getElementById(b.dataset.tab).classList.add('active');document.querySelector('#title').textContent=b.textContent.replace(/^\S+\s/,'');if(b.dataset.tab==='orders')loadOrders();if(b.dataset.tab==='customers')loadCustomers();if(b.dataset.tab==='products')loadTables();});
async function home(){let d=await api('summary');if(!d.ok)return;let x=d.data;['orders','new','today'].forEach(k=>document.querySelector('#m'+k).textContent=x[k]??0);document.querySelector('#mrev').textContent=Number(x.revenue||0).toLocaleString('uz-UZ')+' so‘m';document.querySelector('#quick').innerHTML='<b>📞 '+(await api('settings')).data.phone+'</b><br><br>📍 '+(await api('settings')).data.address+'<br><br>🚚 '+(await api('settings')).data.delivery_note;new Chart(document.getElementById('chart'),{type:'doughnut',data:{labels:['Yangi','Tasdiqlangan','Tayyorlanmoqda','Yetkazilmoqda','Yakunlangan','Bekor'],datasets:[{data:[x.new,x.confirmed,x.preparing,x.delivering,x.completed,x.cancelled]}]},options:{responsive:true,plugins:{legend:{position:'bottom'}}}})}
async function loadOrders(){let f=document.querySelector('#filter').value,d=await api('orders&status='+encodeURIComponent(f));let b=document.querySelector('#ordersBody');b.innerHTML=d.data?.length?d.data.map(x=>`<tr><td>#${x.id}</td><td><b>${esc(x.customer_name)}</b><br><small>${esc(x.note||'')}</small></td><td>${esc(x.phone)}</td><td>${esc(x.address||'')}</td><td><b>${Number(x.amount).toLocaleString('uz-UZ')} so‘m</b></td><td>${new Date(x.created_at).toLocaleString('uz-UZ')}</td><td><select class="badge b-${x.status}" onchange="changeStatus(${x.id},this.value)">${['new','confirmed','preparing','delivering','completed','cancelled'].map(s=>`<option ${s===x.status?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join(''):'<tr><td colspan="7" class="empty">Hozircha buyurtma yo‘q</td></tr>'}
async function changeStatus(id,status){let fd=new FormData();fd.append('id',id);fd.append('status',status);let d=await api('status',{method:'POST',body:fd});toast(d.ok?'Status saqlandi':'Saqlashda xato');home()}
async function loadCustomers(){let d=await api('orders&limit=100'),m={};(d.data||[]).forEach(x=>{let k=x.phone||x.customer_name;if(!m[k])m[k]={name:x.customer_name,phone:x.phone,address:x.address,count:0};m[k].count++});document.querySelector('#customersBody').innerHTML=Object.values(m).map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.phone)}</td><td>${esc(x.address||'')}</td><td>${x.count}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Mijozlar yo‘q</td></tr>'}
async function loadTables(){let d=await api('tables');document.querySelector('#tables').innerHTML=(d.data||[]).map(x=>`<span class="badge" style="margin:4px">${esc(x)}</span>`).join('')}
async function settings(){let d=await api('settings');if(!d.ok)return;for(let [k,v] of Object.entries(d.data))document.querySelector(`[name="${k}"]`)?.setAttribute('value',v)}
document.querySelector('#settingsForm').onsubmit=async e=>{e.preventDefault();let d=await api('settings',{method:'POST',body:new FormData(e.target)});toast(d.ok?'Sozlamalar saqlandi':'Xatolik')};document.querySelector('#logout').onclick=async()=>{await api('logout');location.reload()};function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}home();settings();
</script><?php endif; ?></body></html>